import { useEffect, useRef, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { fileToBase64 } from "./sdk-shim";
import { api, type ApiResponse } from "./api";

type Problem = ApiResponse<typeof api, "appData">["problems"][number];
type View = "today" | "library" | "calendar" | "settings";
type Theme = "system" | "light" | "dark";
type CookieStatus = "none" | "checking" | "valid" | "invalid" | "unknown";
type NoteFieldName = "intuition" | "learnings" | "optimalSolution" | "bruteForceSolution" | "edgeCases";
type NoteImage = Problem["noteImages"][number];

const today = () => new Date().toLocaleDateString("en-CA");
const fmtDate = (d: string | null) => d ? new Intl.DateTimeFormat(undefined,{month:"short",day:"numeric"}).format(new Date(`${d}T12:00:00`)) : "—";
const fmtSubmissionDate = (d: string | null) => d ? new Intl.DateTimeFormat(undefined,{year:"numeric",month:"short",day:"numeric"}).format(new Date(d)) : "Date unavailable";
const messageOf = (e: unknown) => e instanceof Error ? e.message : String(e);

function AutoGrowTextarea({label,value,onChange,onBlur}:{label:string;value:string;onChange:(value:string)=>void;onBlur:()=>void}) {
  const ref=useRef<HTMLTextAreaElement>(null);
  const resize=()=>{const el=ref.current;if(!el)return;const styles=getComputedStyle(el);const lineHeight=Number.parseFloat(styles.lineHeight)||24;const chrome=Number.parseFloat(styles.paddingTop)+Number.parseFloat(styles.paddingBottom)+Number.parseFloat(styles.borderTopWidth)+Number.parseFloat(styles.borderBottomWidth);const maxHeight=Math.ceil(lineHeight*4+chrome);el.style.height="auto";el.style.height=`${Math.min(Math.max(el.scrollHeight,44),maxHeight)}px`;el.style.overflowY=el.scrollHeight>maxHeight?"auto":"hidden"};
  useEffect(resize,[value]);
  return <textarea ref={ref} rows={1} aria-label={label} value={value} onChange={event=>onChange(event.target.value)} onInput={resize} onBlur={onBlur}/>;
}

const noteMarkerPattern=/\[\[image:([0-9a-f-]+)\]\]/gi;

function serializeRichNote(root:HTMLElement){
  const read=(node:Node):string=>{
    if(node.nodeType===Node.TEXT_NODE)return node.textContent??"";
    if(!(node instanceof HTMLElement))return "";
    if(node.tagName==="IMG"&&node.dataset.marker)return `[[image:${node.dataset.marker}]]`;
    if(node.tagName==="BR")return "\n";
    const body=Array.from(node.childNodes).map(read).join("");
    return (node.tagName==="DIV"||node.tagName==="P")?`${body}\n`:body;
  };
  return Array.from(root.childNodes).map(read).join("").replace(/\n{3,}/g,"\n\n").replace(/\n$/,"");
}

function placeCaretAfter(node:Node){const selection=window.getSelection();if(!selection)return;const range=document.createRange();range.setStartAfter(node);range.collapse(true);selection.removeAllRanges();selection.addRange(range)}
function insertNodeAtCaret(root:HTMLElement,node:Node){const selection=window.getSelection();const range=selection?.rangeCount?selection.getRangeAt(0):null;if(!range||!root.contains(range.commonAncestorContainer)){root.append(node);placeCaretAfter(node);return}range.deleteContents();range.insertNode(node);placeCaretAfter(node)}

function NoteTextarea({label,value,onChange,onBlur,field,problemId,token,images,onImageAdded,onImageRemoved,onZoom}:{label:string;value:string;onChange:(value:string)=>void;onBlur:()=>void;field:NoteFieldName;problemId:number;token:string;images:NoteImage[];onImageAdded:(image:NoteImage)=>void;onImageRemoved:(imageId:number)=>void;onZoom:(image:NoteImage)=>void}) {
  const editorRef=useRef<HTMLDivElement>(null);
  const [uploading,setUploading]=useState(false);
  const [error,setError]=useState("");
  const fieldImages=images.filter(image=>image.field===field);
  const renderValue=()=>{
    const editor=editorRef.current;if(!editor)return;
    editor.replaceChildren();
    let cursor=0;
    for(const match of value.matchAll(noteMarkerPattern)){
      const index=match.index??0;
      if(index>cursor)editor.append(document.createTextNode(value.slice(cursor,index)));
      const image=fieldImages.find(item=>item.marker===match[1]);
      if(image){const img=document.createElement("img");img.src=image.url;img.alt=`Pasted ${label} image`;img.dataset.marker=image.marker;img.dataset.imageId=String(image.id);img.contentEditable="false";img.className="inline-note-image";editor.append(img)}
      cursor=index+match[0].length;
    }
    if(cursor<value.length)editor.append(document.createTextNode(value.slice(cursor)));
  };
  useEffect(()=>{const editor=editorRef.current;if(!editor)return;if(document.activeElement!==editor&&serializeRichNote(editor)!==value)renderValue();for(const image of fieldImages){const element=editor.querySelector<HTMLImageElement>(`img[data-marker="${image.marker}"]`);if(element){element.src=image.url;element.dataset.imageId=String(image.id)}}},[value,images]);
  const changed=()=>{const editor=editorRef.current;if(editor)onChange(serializeRichNote(editor))};
  const paste:React.ClipboardEventHandler<HTMLDivElement>=async event=>{
    const file=Array.from(event.clipboardData.files).find(item=>item.type.startsWith("image/"));
    if(!file){event.preventDefault();insertNodeAtCaret(event.currentTarget,document.createTextNode(event.clipboardData.getData("text/plain")));changed();return}
    event.preventDefault();setError("");
    if(!["image/png","image/jpeg","image/webp","image/gif"].includes(file.type)){setError("Paste a PNG, JPEG, WebP, or GIF image.");return}
    if(file.size>8_000_000){setError("Paste an image smaller than 8 MB.");return}
    const marker=crypto.randomUUID();
    const previewUrl=URL.createObjectURL(file);
    const img=document.createElement("img");img.src=previewUrl;img.alt=`Pasted ${label} image`;img.dataset.marker=marker;img.contentEditable="false";img.className="inline-note-image uploading";
    insertNodeAtCaret(event.currentTarget,img);const nextValue=serializeRichNote(event.currentTarget);onChange(nextValue);setUploading(true);
    try{const encoded=await fileToBase64(file);const result=await api.uploadNoteImage({token,problemId,field,marker,dataBase64:encoded.dataBase64,mimeType:encoded.mimeType as "image/png"|"image/jpeg"|"image/webp"|"image/gif",noteText:nextValue});img.src=result.image.url;img.dataset.imageId=String(result.image.id);img.classList.remove("uploading");onImageAdded(result.image)}
    catch(e){img.remove();onChange(serializeRichNote(event.currentTarget));setError(messageOf(e))}
    finally{URL.revokeObjectURL(previewUrl);setUploading(false)}
  };
  const input=()=>{const editor=editorRef.current;if(!editor)return;const presentMarkers=new Set(Array.from(editor.querySelectorAll<HTMLImageElement>("img[data-marker]")).map(image=>image.dataset.marker));for(const image of fieldImages){if(!presentMarkers.has(image.marker)){void api.deleteNoteImage({token,problemId,imageId:image.id,noteText:serializeRichNote(editor)}).then(()=>onImageRemoved(image.id)).catch(e=>setError(messageOf(e)))}}changed()};
  return <div className="note-input"><div ref={editorRef} className="rich-note-editor" role="textbox" aria-multiline="true" aria-label={label} contentEditable={!uploading} suppressContentEditableWarning onInput={input} onBlur={()=>{changed();onBlur()}} onPaste={paste} onKeyDown={event=>{if(event.key==="Enter"){event.preventDefault();insertNodeAtCaret(event.currentTarget,document.createTextNode("\n"));changed()}}} onClick={event=>{const target=event.target;if(target instanceof HTMLImageElement&&target.dataset.imageId){const image=fieldImages.find(item=>item.id===Number(target.dataset.imageId));if(image)onZoom(image)}}}/>{uploading&&<small className="image-paste-status" role="status">Saving pasted image…</small>}{error&&<small className="error" role="alert">{error}</small>}</div>;
}

// Storage can be unavailable in privacy-restricted browser/webview contexts.
// Treat it as an optional convenience so a blocked storage API never prevents
// the access screen from rendering.
const safeStorage = {
  get(kind: "local" | "session", key: string) {
    try { return (kind === "local" ? window.localStorage : window.sessionStorage).getItem(key); }
    catch { return null; }
  },
  set(kind: "local" | "session", key: string, value: string) {
    try { (kind === "local" ? window.localStorage : window.sessionStorage).setItem(key, value); }
    catch { /* The current React session still works without persistence. */ }
  },
  remove(kind: "local" | "session", key: string) {
    try { (kind === "local" ? window.localStorage : window.sessionStorage).removeItem(key); }
    catch { /* Nothing to clear when storage is unavailable. */ }
  },
};

